def review_game(blotter, true_value):
    """blotter: list of (side, size, price), side "buy"
    or "sell". Return (per_trade, total): each trade's
    P&L at true_value, and their sum."""
    per = []
    for side, size, price in blotter:
        if side == "sell":
            per.append(size * (price - true_value))
        else:
            per.append(size * (true_value - price))
    return per, sum(per)
